document.addEventListener("click",e=>{const t=e.target.closest?.("[data-nova-team-filter]"),a=t?t.closest(".nova-team"):null;if(!a)return;const r=t.dataset.novaTeamFilter;a.querySelectorAll("[data-nova-team-filter]").forEach(e=>e.setAttribute("aria-pressed",String(e===t))),a.querySelectorAll("[data-nova-team-role]").forEach(e=>{e.hidden=""!==r&&e.dataset.novaTeamRole!==r})});